-- 커뮤니티 탭의 제휴 배너. 관리 API 없이 운영자가 로컬 관리 페이지(admin-local)나 SQL로 직접 넣고 고친다.
-- 관리 페이지가 SQL로 바로 넣으므로 생성·수정 시각에 기본값을 둔다.
-- 노출 기간은 한국 날짜 기준이고 양 끝을 포함한다. 기간이 비어 있으면 상시 노출한다.
CREATE TABLE "partner_banners" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "kind" VARCHAR(20) NOT NULL,
    "partner_name" VARCHAR(50) NOT NULL,
    "partner_kind" VARCHAR(30),
    "title" VARCHAR(100) NOT NULL,
    "image_url" VARCHAR(512) NOT NULL,
    "image_background" VARCHAR(9) NOT NULL DEFAULT '#ffffff',
    "link_url" VARCHAR(1024) NOT NULL,
    "link_label" VARCHAR(30),
    "description" VARCHAR(500),
    "benefit" VARCHAR(100),
    "place" VARCHAR(100),
    "validity_label" VARCHAR(50),
    "shared_code" VARCHAR(50),
    "disclosure" BOOLEAN NOT NULL DEFAULT FALSE,
    "starts_on" DATE,
    "ends_on" DATE,
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "active" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "chk_partner_banners_kind" CHECK ("kind" IN ('BENEFIT', 'INTRODUCTION')),
    CONSTRAINT "chk_partner_banners_benefit_fields" CHECK (
        "kind" <> 'BENEFIT'
        OR ("benefit" IS NOT NULL AND "place" IS NOT NULL AND "validity_label" IS NOT NULL
            AND "starts_on" IS NOT NULL AND "ends_on" IS NOT NULL)
    ),
    CONSTRAINT "chk_partner_banners_introduction_fields" CHECK (
        "kind" <> 'INTRODUCTION' OR ("description" IS NOT NULL AND "link_label" IS NOT NULL)
    ),
    CONSTRAINT "chk_partner_banners_period" CHECK ("starts_on" IS NULL OR "ends_on" IS NULL OR "starts_on" <= "ends_on")
);

CREATE INDEX "idx_partner_banners_active_sort" ON "partner_banners" ("active", "sort_order");
